for i,(kind,r) in enumerate([('graph',r) for r in ref['observations']]+[('numeric',r) for r in ref['numeric_observations']]):
 x=Path(f'build/heuristic-precision-{i}.xes');x.write_text(r['xes'],encoding='utf-8');out=x.with_suffix('.json')
 cmd=[str(exe),str(x),'--heuristic-variant',r['variant'].lower(),'-o',str(out)]
