 except subprocess.TimeoutExpired:row.update(timeout=True)
 row['matched']=row.get('actual')==row['expected'];checks.append(row)
 if (i+1)%80==0:print(i+1,'cases checked',flush=True)
report={'checks':checks,'native_executable_sha256':hashlib.sha256(exe.read_bytes()).hexdigest()};Path(a.output).write_text(json.dumps(report,indent=2)+'\n',encoding='utf-8');print(sum(c['matched'] for c in checks),'/',len(checks));print([c['index'] for c in checks if not c['matched']])
